/// <summary>
/// find
/// </summary>
/// <param name = "_nDX_SNClientDeactive">temp buffer</param>
/// <param name = "_company">company</param>
/// <param name = "_custAccount">cust account</param>
/// <param name = "_update">forupdate</param>
/// <returns>NDXSNClientDeactiveTmp record</returns>
static NDXSNClientDeactiveTmp find(NDXSNClientDeactiveTmp  _nDX_SNClientDeactive,
                                NDXCompanyBe _company,
                                CustAccount _custAccount,
                                boolean _update = false)
{
    NDXSNClientDeactiveTmp nDXSNClientDeactiveTmp = _nDX_SNClientDeactive;

    nDXSNClientDeactiveTmp.selectForUpdate(_update);

    select firstonly nDXSNClientDeactiveTmp
        where nDXSNClientDeactiveTmp.Company == _company &&
              nDXSNClientDeactiveTmp.Child == _custAccount;

    return nDXSNClientDeactiveTmp;
}

/// <summary>
/// find or create
/// </summary>
/// <param name = "_nDX_SNClientDeactive">temp buffer</param>
/// <param name = "_company">company</param>
/// <param name = "_custAccount">cust account</param>
/// <param name = "_partyRecId">party rec id</param>
/// <returns>NDXSNClientDeactiveTmp record</returns>
static NDXSNClientDeactiveTmp findOrCreate(NDXSNClientDeactiveTmp  _nDX_SNClientDeactive, NDXCompanyBE _company, CustAccount _custAccount, DirPartyRecId _partyRecId)
{
    NDXSNClientDeactiveTmp nDXSNClientDeactiveTmp = _nDX_SNClientDeactive;

    nDXSNClientDeactiveTmp = NDXSNClientDeactiveTmp::find(nDXSNClientDeactiveTmp, _company, _custAccount, true);

    if (!nDXSNClientDeactiveTmp)
    {
        nDXSNClientDeactiveTmp.Company          = _company;
        nDXSNClientDeactiveTmp.Child            = _custAccount;
        nDXSNClientDeactiveTmp.PartyRefRecId    = _partyRecId;
        nDXSNClientDeactiveTmp.CustName   = CustTable::findByCompany(NDXHelperCommon::NDXCompanys2CompanyId(_company), _custAccount).name();
        nDXSNClientDeactiveTmp.insert();
    }

    return nDXSNClientDeactiveTmp;
}
